import type { Chapter, ChapterTest, Example, Exercise, Lesson, LessonKind } from "../data/types";
import { pythonDebugLabs } from "./pythonDebugLabs";
import { pythonGapLessons } from "./pythonGaps";

type ExampleSeed = {
  title: string;
  code: string;
  output: string;
  explanation: string;
  reasons?: string[];
  mistakes?: Example["mistakes"];
};

export type LessonSeed = Omit<Lesson, "id" | "chapter" | "order" | "examples" | "exercise"> & {
  title: string;
  examples: ExampleSeed[];
  exercise: Exercise;
};

type ChapterSeed = {
  number: number;
  title: string;
  description: string;
  lesson: LessonSeed;
  project: Exercise & { title: string; brief: string; acceptanceCriteria: string[] };
  test: ChapterTest[];
};

const defaultMistakes: Example["mistakes"] = [
  { mistake: "Misspelling a name or keyword", error: "NameError or SyntaxError", fix: "Compare every name and keyword with the example. Python is case-sensitive." },
  { mistake: "Changing the indentation in a block", error: "IndentationError or an unexpected result", fix: "Keep every line that belongs to the block indented by the same four spaces." },
  { mistake: "Changing punctuation such as a colon, comma, or parenthesis", error: "SyntaxError: invalid syntax", fix: "Match the punctuation to the construct you are using before running again." },
];

function makeExample(seed: ExampleSeed): Example {
  const codeLines = seed.code.split("\n");
  return {
    title: seed.title,
    code: seed.code,
    output: seed.output,
    explanation: seed.explanation,
    lines: codeLines.map((line, index) => {
      const shown = line.length ? `\`${line}\`` : "A blank line";
      const reason = seed.reasons?.[index] ?? explainGeneratedLine(line);
      return `Line ${index + 1}: ${shown}. ${reason}`;
    }),
    mistakes: seed.mistakes ?? defaultMistakes,
  };
}

function explainGeneratedLine(line: string) {
  const trimmed = line.trim();
  if (!trimmed) return "The blank line has no runtime effect; it separates ideas so a person can scan the program more easily.";
  if (trimmed.startsWith("#")) return "This is a comment. Python ignores it at runtime, while it gives a reader context for the next operation.";
  if (trimmed.startsWith("@")) return "This decorator changes or configures the definition immediately below it before the program uses that definition.";
  if (trimmed.startsWith("import ") || trimmed.startsWith("from ")) return "This import makes a standard-library name available so the program can use that capability explicitly.";
  if (trimmed.startsWith("async def ")) return "async def defines a coroutine function. Calling it creates work for an event loop instead of running the body immediately.";
  if (trimmed.startsWith("def ")) return "def defines a reusable function. Its parameters receive caller values, and the colon begins the indented body.";
  if (trimmed.startsWith("class ")) return "class defines a reusable blueprint. The indented statements below describe data or behavior for instances of that type.";
  if (trimmed.startsWith("if ") || trimmed.startsWith("elif ")) return "This condition evaluates to True or False. The colon begins the indented branch Python chooses when the condition is true.";
  if (trimmed === "else:") return "else starts the alternative branch that Python runs when the related condition was false.";
  if (trimmed.startsWith("for ") || trimmed.startsWith("while ")) return "This loop header controls repeated work. The colon begins the block that Python runs for each permitted iteration.";
  if (trimmed.startsWith("try:")) return "try begins a block that may raise an expected exception, letting a later except branch handle that failure deliberately.";
  if (trimmed.startsWith("except ")) return "except selects a recovery path for the named expected exception instead of leaving the program in an unclear state.";
  if (trimmed.startsWith("with ")) return "with enters a context manager, which performs setup now and guarantees cleanup when the indented block exits.";
  if (trimmed.startsWith("return ")) return "return evaluates this expression, sends the resulting value back to the caller, and ends the current function call.";
  if (trimmed.startsWith("print(")) return "print evaluates its argument and writes the resulting value to the output console, making the current program state visible.";
  if (/^[\w.\[\]]+\s*(\+=|-=|\*=|\/=|=)/.test(trimmed)) return "The assignment evaluates the expression on the right, then stores or updates the named value on the left so later lines can reuse it.";
  return "Python evaluates this statement in top-to-bottom order. Its result or side effect contributes to the focused behavior demonstrated by the example.";
}

/**
 * `kind` names the activity the lesson actually is. Every other course labels its lessons this way;
 * Python seeds are authored individually, so the label is passed by the slot that built the lesson.
 */
export function makeLesson(chapter: number, seed: LessonSeed, order = 1, kind: LessonKind = "learn"): Lesson {
  return {
    id: `python-${chapter}-${order}`,
    chapter,
    order,
    kind,
    title: seed.title,
    minutes: seed.minutes,
    summary: seed.summary,
    learningGoals: seed.learningGoals,
    explanation: seed.explanation,
    keywordNotes: seed.keywordNotes,
    examples: seed.examples.map(makeExample),
    exercise: seed.exercise,
    recap: seed.recap,
    decisionGuide: seed.decisionGuide,
  };
}

let masteryLessons: Record<number, LessonSeed> = {};
let appliedLessons: Record<number, LessonSeed> = {};
let implementationLessons: Record<number, LessonSeed> = {};
let integrationLessons: Record<number, LessonSeed> = {};
let caseStudyLessons: Record<number, LessonSeed> = {};
let challengeLessons: Record<number, LessonSeed> = {};
let gapLessons: Record<number, LessonSeed> = {};

function buildChapter(seed: ChapterSeed): Chapter {
  // Slots 1-4 are the authored learn lessons, slot 5 the integration workflow, slot 6 the case
  // study, and slot 7 the challenge. Slot 8 belongs to the authored debugging lab where the
  // chapter has one, so the activity a learner meets is named by the slot that built it. The
  // deep-dive gap material then continues after the lab, which keeps every order contiguous.
  const lessons: Lesson[] = [
    makeLesson(seed.number, seed.lesson, 1, "learn"),
    makeLesson(seed.number, masteryLessons[seed.number], 2, "learn"),
    makeLesson(seed.number, appliedLessons[seed.number], 3, "learn"),
    makeLesson(seed.number, implementationLessons[seed.number], 4, "learn"),
    makeLesson(seed.number, integrationLessons[seed.number], 5, "integration"),
    makeLesson(seed.number, caseStudyLessons[seed.number], 6, "case-study"),
    makeLesson(seed.number, challengeLessons[seed.number], 7, "challenge"),
  ];
  let order = 8;
  if (pythonDebugLabs[seed.number]) lessons.push(makeLesson(seed.number, pythonDebugLabs[seed.number], order++, "debug"));
  if (gapLessons[seed.number]) lessons.push(makeLesson(seed.number, gapLessons[seed.number], order++, "learn"));
  for (const gapLesson of pythonGapLessons[seed.number] ?? []) lessons.push(makeLesson(seed.number, gapLesson, order++, "learn"));
  return {
    number: seed.number,
    title: seed.title,
    description: seed.description,
    major: true,
    lessons,
    project: seed.project,
    test: seed.test,
    cumulativeTest: seed.number % 5 === 0 ? cumulativeQuestions(seed.number) : undefined,
    available: true,
  };
}

const q = (question: string, choices: string[], correctIndex: number, explanation: string): ChapterTest => ({ question, choices, correctIndex, explanation });
const cumulativeBank = new Map<number, ChapterTest>();

function cumulativeQuestions(chapter: number): ChapterTest[] {
  return Array.from({ length: chapter }, (_, index) => cumulativeBank.get(index + 1)).filter((question): question is ChapterTest => Boolean(question));
}

